{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Viqualine, the closest analogue (Morgan 0.41), shares the 6-methoxyquinoline and vinyl-piperidine scaffold and showed absolute oral bioavailability of 73 ± 7% in healthy volunteers, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Lenvatinib, which contains the same 6-methoxyquinoline core, has an estimated absolute oral bioavailability of about 85% in humans, supporting favorable oral absorption for this quinoline chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Alizapride, a basic methoxy-substituted heteroaromatic drug, had ~90% systemic availability after oral dosing, indicating that strongly basic amines with similar polarity can still be well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Tegaserod has low absolute bioavailability (~10%), but it is structurally distant (Morgan ~0.21) and its low F is driven by extensive first-pass metabolism; this contradictory evidence is outweighed by closer high-F analogues and favorable physicochemical properties.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogue viqualine has high absolute oral bioavailability (73–80%) and shares the key 6-methoxyquinoline and vinyl-amine features. Other methoxyquinoline/basic-amine drugs also show high F. Low-F comparators are structurally distant and less transferable. Physicochemical properties are favorable for absorption. Therefore the query is predicted to have F ≥ 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Closest analogue similarity is only ~0.41, limiting quantitative transfer.",
    "Metabolic stability and solubility are not experimentally assessed.",
    "Possible first-pass metabolism or transporter effects are not captured by the physicochemical prior."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

